"""quality-check 任务监视器。

用法:
    python tools/qc_status.py             # 打印进度看板
    python tools/qc_status.py --write     # 同时写入 wiki/outputs/quality-check-进度看板.md
    python tools/qc_status.py --json      # 机器可读输出

数据来源:
    .qc/queue.json   批次队列
    .qc/LEDGER.md    批次状态（🔄 / ✅ 标记）
    wiki/**/*.md     页面的 qc_status 字段（落盘进度，最可靠）
"""
import sys, os, re, json, glob, argparse, datetime


ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
os.chdir(ROOT)
sys.path.insert(0, "tools")
from kb_lib import read_text, qc_input  # noqa: E402
import kb_lib as K
K.console_encoding()

# ⚠️ 不拼相对路径 `.qc/…`：qc_input 会「先新后旧」解析
#    （env MATSCI_QC_DIR > 库根 .qc/ > 历史归档；详见 kb_lib.qc_work_dir 的注释）。
QUEUE = qc_input("queue.json")
LEDGER = qc_input("LEDGER.md")
BOARD = "wiki/outputs/quality-check-进度看板.md"

# 批次顺序与阶段不再写死任何具体批次号：顺序从 queue.json 的键动态派生，
# 阶段映射留空（全部归「其他」）——任何批次命名方案都适用。
STAGE = {}


def batch_order(Q):
    return sorted(Q.keys())


def load_queue():
    if not os.path.exists(QUEUE):
        return {}
    with open(QUEUE, encoding="utf-8") as f:
        return json.load(f)


def ledger_states():
    """从 LEDGER.md 解析各批次的 🔄 / ✅ 标记。

    解析口径（历史教训的泛化，不绑任何具体库的批次号/台账）：
      · 不要求固定列数：批次计划表与执行日志表列数不同。按行解析——
        先把 `||` 拆成多行片段，再对每个片段取**首个**批号与
        **含状态标记的那个单元格**作为状态列，只认 ✅（done）/ 🔄（running）/ ⏳（pending）。
      · 批号正则放宽为 `[A-Z]{1,2}\\d+`（写死批号会让队列里的新批次永远解析不出来）；
        状态列**按内容**找，不得取「最后一列」——那可能是备注。
      · 「批次执行日志」行以 `FIXED n / VERIFIED m` 为真签名：一行存在本身即「已完成」。
    """
    st = {}
    if not os.path.exists(LEDGER):
        return st
    txt = read_text(LEDGER)
    # 「批次执行日志」行的**真签名**：结论列写着 `FIXED n / VERIFIED m`。
    # 用真签名而不是"第几列"或"有没有某标记"——后者正是本库反复踩的坑
    # （把规范当实况、把近似当判据）。
    _EXEC = re.compile(r"FIXED\s*\d|VERIFIED\s*\d", re.I)
    for raw_line in txt.split("\n"):
        line = raw_line.strip()
        if not line.startswith("|"):
            continue
        # 同一行可能塞了多个批次（用 `||` 分隔）——先拆开
        for seg in line.split("||"):
            seg = seg.strip()
            if not seg.startswith("|"):
                continue
            cells = [c.strip() for c in seg.strip("|").split("|")]
            if len(cells) < 2:
                continue
            m = re.match(r"\*{0,2}([A-Z]{1,2}\d+)\*{0,2}$", cells[0])
            if not m:
                continue
            bid = m.group(1)
            # 状态列按**内容**定位；找不到标记就跳过（不要把备注当状态）
            marks = next((c for c in cells[1:]
                          if any(k in c for k in ("✅", "🔄", "⏳"))), "")
            if "✅" in marks:
                st[bid] = "done"
            elif "🔄" in marks:
                st[bid] = "running"
            elif "⏳" in marks:
                st.setdefault(bid, "pending")
            elif _EXEC.search(seg):
                # 「批次执行日志」表**不带状态标记**——一行存在本身即「已完成」。
                # 不回填的话，15 行已完成批次永远读不出来（看板长期显示 0/19）。
                st[bid] = "done"
    return st


def graded_pages():
    """扫描全库 qc_status 字段。"""
    fixed, verified, other = [], [], []
    for f in glob.glob("wiki/**/*.md", recursive=True):
        if "/.index/" in f.replace("\\", "/") or "/.claude-rename/" in f.replace("\\", "/"):
            continue
        tot = read_text(f)
        m = re.search(r"^qc_status:\s*(\S+)", tot, re.M)
        if not m:
            continue
        v = m.group(1).strip().strip("\"'")
        rel = os.path.relpath(f, "wiki").replace("\\", "/")[:-3]
        if v == "fixed":
            fixed.append(rel)
        elif v == "verified":
            verified.append(rel)
        else:
            other.append((rel, v))
    return fixed, verified, other


def bar(done, total, width=28):
    if total <= 0:
        return "░" * width
    k = int(round(done / total * width))
    return "█" * k + "░" * (width - k)


def selftest():
    """校验器自检：合成夹具（正例 + 反例），不断言任何具体库的当前状态。"""
    import tempfile
    ok = True
    global QUEUE, LEDGER
    saved_q, saved_l = QUEUE, LEDGER
    saved_env = os.environ.get("MATSCI_QC_DIR")
    with tempfile.TemporaryDirectory() as td:
        qdir = os.path.join(td, ".qc")
        os.makedirs(qdir)
        with open(os.path.join(qdir, "queue.json"), "w", encoding="utf-8") as f:
            json.dump({"B1": ["页甲"], "B2": ["页乙"]}, f, ensure_ascii=False)
        with open(os.path.join(qdir, "LEDGER.md"), "w", encoding="utf-8") as f:
            f.write("| 批次 | 状态 |\n|---|---|\n| **B1** | ✅ |\n| B2 | 🔄 |\n")
        os.environ["MATSCI_QC_DIR"] = qdir
        try:
            QUEUE, LEDGER = qc_input("queue.json"), qc_input("LEDGER.md")
            q = load_queue()
            good = isinstance(q, dict) and len(q) == 2
            print(f"  [{'ok' if good else 'FAIL'}] 合成队列可解析 -> {len(q)} 批")
            ok = ok and good
            st = ledger_states()
            good = st.get("B1") == "done" and st.get("B2") == "running"
            print(f"  [{'ok' if good else 'FAIL'}] 合成台账解析出 done/running -> {st}")
            ok = ok and good
        finally:
            if saved_env is None:
                os.environ.pop("MATSCI_QC_DIR", None)
            else:
                os.environ["MATSCI_QC_DIR"] = saved_env
            QUEUE, LEDGER = saved_q, saved_l
    # 反例：不存在的文件不得被误报为存在
    p = qc_input("绝不存在的-xyz.json")
    print(f"  [{'ok' if not os.path.exists(p) else 'FAIL'}] 反例 不存在的文件未被误报")
    ok = ok and not os.path.exists(p)
    print("=== selftest", "PASS ===" if ok else "FAIL ===")
    return 0 if ok else 1


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--write", action="store_true", help="写出 Markdown 看板")
    ap.add_argument("--json", action="store_true", help="JSON 输出")
    ap.add_argument("--selftest", action="store_true", help="校验器自检")
    a = ap.parse_args()

    if a.selftest:
        return selftest()

    Q = load_queue()
    st = ledger_states()
    fixed, verified, other = graded_pages()

    # 队列里所有页面的全集
    allq = set()
    for v in Q.values():
        allq.update(v)
    total_pages = len(allq)
    graded = len(fixed) + len(verified)
    # 已评分中属于本队列的比例
    graded_in_q = len([p for p in fixed + verified
                       if p.split("/")[-1] in allq])

    n_done = sum(1 for b in Q if st.get(b) == "done")
    n_run = sum(1 for b in Q if st.get(b) == "running")
    n_tot = len(Q)

    # 阶段汇总
    stages = {}
    for b, pages in Q.items():
        s = STAGE.get(b, "其他")
        d = stages.setdefault(s, [0, 0])
        d[0] += len(pages)
        if st.get(b) == "done":
            d[1] += len(pages)

    if a.json:
        print(json.dumps({
            "batches_total": n_tot, "batches_done": n_done, "batches_running": n_run,
            "pages_queued": total_pages, "pages_graded": graded,
            "fixed": len(fixed), "verified": len(verified),
            "stages": stages,
            "batch_state": {b: st.get(b, "pending") for b in Q},
        }, ensure_ascii=False, indent=1))
        return 0

    L = []
    L.append("╔" + "═" * 66 + "╗")
    L.append("║" + " quality-check 任务监视器".ljust(60) + "║")
    L.append("║" + (" " + datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S"))
                 .ljust(60) + "║")
    L.append("╚" + "═" * 66 + "╝")
    L.append("")
    L.append(f"  批次进度   {bar(n_done, n_tot)}  {n_done}/{n_tot} 批")
    L.append(f"  页面评分   {bar(graded_in_q, total_pages)}  {graded_in_q}/{total_pages} 页")
    L.append("")
    if n_run:
        running = [b for b in Q if st.get(b) == "running"]
        L.append(f"  ▶ 正在运行: {', '.join(running)}")
    else:
        L.append("  ▶ 无批次在运行")
    L.append("")
    L.append("  阶段                       页数   已完成")
    L.append("  " + "─" * 44)
    for s in sorted(stages):
        if s in stages:
            tot, dn = stages[s]
            L.append(f"  {s:<22} {tot:>5}   {dn:>5}  {bar(dn, tot, 16)}")
    L.append("")
    L.append("  批次明细")
    L.append("  " + "─" * 44)
    line = "  "
    for b in batch_order(Q):
        if b not in Q:
            continue
        sym = {"done": "✅", "running": "🔄"}.get(st.get(b), "⏳")
        line += f"{b}{sym} "
        if len(line) > 56:
            L.append(line)
            line = "  "
    if line.strip():
        L.append(line)
    L.append("")
    L.append(f"  已修正 {len(fixed)} 页 ｜ 已核验 {len(verified)} 页")
    if other:
        L.append(f"  ⚠ 非标准 qc_status 值 {len(other)} 处")
    print("\n".join(L))

    if a.write:
        lines = ["---", "created: " + datetime.date.today().isoformat(), "updated: "
                 + datetime.date.today().isoformat(), "type: output",
                 "tags: [quality-check, progress, dashboard]",
                 "aliases:", "  - quality-check 进度看板", "  - QC 监视器",
                 'summary: "quality-check 任务实时进度看板（由 tools/qc_status.py 自动生成）"',
                 "---", "", "# quality-check 进度看板", "",
                 f"> 自动生成于 {datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')}"
                 " ｜ 数据源：`.qc/` 与各页面 `qc_status` 字段", "",
                 "## 总进度", "",
                 f"| 指标 | 进度 |", "|------|------|",
                 f"| 批次 | {bar(n_done, n_tot, 20)} {n_done}/{n_tot} |",
                 f"| 页面评分 | {bar(graded_in_q, total_pages, 20)} {graded_in_q}/{total_pages} |",
                 f"| 已修正 | {len(fixed)} 页 |", f"| 已核验 | {len(verified)} 页 |",
                 "", "## 阶段", "", "| 阶段 | 页数 | 已完成 |", "|------|------|--------|"]
        for s in sorted(stages):
            if s in stages:
                tot, dn = stages[s]
                lines.append(f"| {s} | {tot} | {dn} |")
        lines += ["", "## 批次明细", "",
                  "| 批次 | 阶段 | 页数 | 状态 |", "|------|------|------|------|"]
        for b in batch_order(Q):
            if b not in Q:
                continue
            sym = {"done": "✅ 完成", "running": "🔄 运行中"}.get(st.get(b), "⏳ 待启动")
            lines.append(f"| {b} | {STAGE.get(b,'')} | {len(Q[b])} | {sym} |")
        if fixed or verified:
            lines += ["", "## 已处理的页面", "", "### 已修正", ""]
            lines += [f"- [[{p}]]" for p in sorted(fixed)]
            lines += ["", "### 已核验（无改动）", ""]
            lines += [f"- [[{p}]]" for p in sorted(verified)]
        os.makedirs(os.path.dirname(BOARD), exist_ok=True)
        with open(BOARD, "w", encoding="utf-8", newline="\n") as f:
            f.write("\n".join(lines) + "\n")
        print(f"\n  已写出看板 → {BOARD}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
